-- LuckyEngine script project. Produces .sln/.csproj files your scripts build from.
--
-- This file was generated by LuckyEngine, but it is now yours. Customize it freely, but keep the hazel-dir option and
-- include ScriptProject.Generated.lua to connect it to LuckyEditor.

-- Path to LuckyEngine's root, for the assembly references below. The editor always passes --hazel-dir
newoption {
	trigger     = "hazel-dir",
	value       = "PATH",
	description = "Absolute path to the LuckyEngine installation this project belongs to"
}
HazelRootDirectory = _OPTIONS["hazel-dir"]

-- Fail before generation rather than writing engine references that only surface as C# errors later.
if not HazelRootDirectory or not os.isfile(path.join(HazelRootDirectory, "Resources", "Scripts", "Hazel-ScriptCore.dll")) then
	error("LuckyEngine was not found at '" .. (HazelRootDirectory or "<not provided>") .. "'.\n" ..
		"Run the CreateScriptProjects script next to this file, or pass --hazel-dir=<engine install dir>.")
end

-- The assembly name and project-relative directories, written from the .hproj on every project open.
local generated = path.join(_SCRIPT_DIR, "ScriptProject.Generated.lua")
if not os.isfile(generated) then
	error("'" .. generated .. "' was not found. Open this project in LuckyEditor to write it.")
end
include(generated)

workspace (ScriptAssemblyName)
	targetdir "build"
	startproject (ScriptAssemblyName)
	configurations { "Debug", "Release", "Dist" }

project (ScriptAssemblyName)
	location (ScriptClientDirectory)
	kind "SharedLib"
	language "C#"
	dotnetframework "net9.0"

	targetname (ScriptAssemblyName)
	targetdir (ScriptBinariesDirectory)
	objdir (ScriptIntermediatesDirectory)

	vsprops {
		AppendTargetFrameworkToOutputPath = "false",
		Nullable = "enable",
		CopyLocalLockFileAssemblies = "true",
		EnableDynamicLoading = "true",
		RollForward = "Major",
	}

	files {
		path.join(AssetsDirectory, "**.cs"),
	}
	-- Intermediates hold *.AssemblyInfo.cs, which would be a CS0579 duplicate attribute. A '~'-suffixed folder is the
	-- opt-out for vendored .cs you don't want compiled.
	removefiles {
		path.join(ScriptBinariesDirectory, "**"),
		path.join(ScriptIntermediatesDirectory, "**"),
		path.join(AssetsDirectory, "**~/**"),
	}

	-- LuckyEngine's C# API.
	links {
		path.join(HazelRootDirectory, "Resources", "Scripts", "Hazel-ScriptCore.dll"),
		path.join(HazelRootDirectory, "Resources", "Scripts", "Coral.Managed.dll")
	}

	filter "Debug"
		optimize "Off"
		symbols "Default"

	filter "Release"
		optimize "On"
		symbols "Default"

	filter "Dist"
		optimize "Full"
		symbols "Off"
